### Calculating Distance from Microseconds

Sound travels through room-temperature air at approximately **343 meters per second**, which equals **0.0343 centimeters per microsecond**:

```cpp
const int trigPin = 9;
const int echoPin = 10;

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  Serial.begin(9600);
}

void loop() {
  // 1. Send 10µs trigger pulse
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // 2. Measure round-trip echo pulse duration
  long duration = pulseIn(echoPin, HIGH);

  // 3. Distance formula: divide by 2 for one-way distance!
  float distanceCm = (duration * 0.0343) / 2.0;

  Serial.print("Distance: ");
  Serial.print(distanceCm);
  Serial.println(" cm");
  delay(200);
}
```

